"use client";

import {
  type ComponentPropsWithoutRef,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

import { animate, type AnimationPlaybackControls } from "motion/react";

import { cn } from "@/lib/utils";

// Read live rather than once, so a visitor who changes the setting mid-visit is honoured.
function usePrefersReducedMotion() {
  const [reduce, setReduce] = useState(false);

  useEffect(() => {
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduce(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  return reduce;
}

function CheckGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="m3 8.5 3.25 3.25L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

// Releasing early drains the fill from wherever it stopped, on a critically
// damped spring, so the person sees the hold undo itself.
const DRAIN = { type: "spring", stiffness: 500, damping: 45, mass: 1 } as const;

/**
 * Says whether the visitor confirmed by pointer or by keyboard, so the caller can answer in
 * kind.
 */
export type ConfirmationInput = "keyboard" | "pointer";

/**
 * Where the button is in its hold cycle.
 */
export type HoldStatus = "idle" | "holding" | "confirmed";

/**
 * Sets how long the hold runs, what the confirmed state shows, and when it resets.
 */
export type HoldToConfirmButtonProps = Omit<
  ComponentPropsWithoutRef<"button">,
  "children" | "onClick"
> & {
  children?: ReactNode;
  confirmedContent?: ReactNode;
  duration?: number;
  onConfirm: (input: ConfirmationInput) => void;
  resetAfter?: number;
};

/**
 * Requires a sustained press before a destructive action fires, so a stray click cannot
 * trigger it.
 */
export function HoldToConfirmButton({
  children = "Hold to confirm",
  className,
  confirmedContent,
  disabled,
  duration = 1600,
  onConfirm,
  resetAfter = 1800,
  ...buttonProps
}: HoldToConfirmButtonProps) {
  const [status, setStatus] = useState<HoldStatus>("idle");
  // The fill is painted straight onto its element each frame. A React state
  // update per frame would re-render the button sixty times a second.
  const fillRef = useRef<HTMLSpanElement>(null);
  const drainRef = useRef<AnimationPlaybackControls | null>(null);
  const activePointerRef = useRef<number | null>(null);
  const activeInputRef = useRef<ConfirmationInput | null>(null);
  const activeKeyRef = useRef<string | null>(null);
  const animationFrameRef = useRef<number | null>(null);
  const resetTimerRef = useRef<number | null>(null);
  const onConfirmRef = useRef(onConfirm);
  const startedAtRef = useRef(0);
  const confirmedRef = useRef(false);
  const prefersReducedMotion = usePrefersReducedMotion();

  const paint = useCallback(
    (progress: number, drain = false) => {
      const fill = fillRef.current;
      if (!fill) return;
      drainRef.current?.stop();
      drainRef.current = null;
      if (drain && !prefersReducedMotion) {
        drainRef.current = animate(fill, { scaleX: progress }, DRAIN);
        return;
      }
      fill.style.transform = `scaleX(${progress})`;
    },
    [prefersReducedMotion],
  );

  useEffect(() => {
    onConfirmRef.current = onConfirm;
  }, [onConfirm]);

  const clearAnimationFrame = useCallback(() => {
    if (animationFrameRef.current === null) return;
    window.cancelAnimationFrame(animationFrameRef.current);
    animationFrameRef.current = null;
  }, []);

  const reset = useCallback(() => {
    clearAnimationFrame();
    confirmedRef.current = false;
    activePointerRef.current = null;
    activeInputRef.current = null;
    activeKeyRef.current = null;
    paint(0, true);
    setStatus("idle");
  }, [clearAnimationFrame, paint]);

  const complete = useCallback(() => {
    if (confirmedRef.current) return;
    confirmedRef.current = true;
    const input = activeInputRef.current ?? "pointer";
    activeInputRef.current = null;
    clearAnimationFrame();
    paint(1);
    setStatus("confirmed");
    onConfirmRef.current(input);

    if (resetAfter > 0) {
      resetTimerRef.current = window.setTimeout(reset, resetAfter);
    }
  }, [clearAnimationFrame, paint, reset, resetAfter]);

  const updateProgress = useCallback(() => {
    const safeDuration = Math.max(1, duration);
    const nextProgress = Math.min(1, (performance.now() - startedAtRef.current) / safeDuration);
    paint(nextProgress);
    if (nextProgress >= 1) {
      complete();
      return;
    }
    animationFrameRef.current = window.requestAnimationFrame(updateProgress);
  }, [complete, duration, paint]);

  const begin = useCallback(
    (input: ConfirmationInput) => {
      if (disabled || status !== "idle" || activeInputRef.current !== null) return false;
      activeInputRef.current = input;
      confirmedRef.current = false;
      startedAtRef.current = performance.now();
      paint(0);
      setStatus("holding");
      animationFrameRef.current = window.requestAnimationFrame(updateProgress);
      return true;
    },
    [disabled, paint, status, updateProgress],
  );

  const cancel = useCallback(() => {
    if (confirmedRef.current) return;
    reset();
  }, [reset]);

  // Disabling the button mid-hold cancels the hold. The status adjusts during
  // render, then the effect below stops the frame loop and drains the fill.
  const [wasDisabled, setWasDisabled] = useState(disabled);
  if (disabled !== wasDisabled) {
    setWasDisabled(disabled);
    if (disabled && status === "holding") setStatus("idle");
  }

  useEffect(() => {
    if (status === "idle" && activeInputRef.current !== null) cancel();
  }, [cancel, status]);

  useEffect(
    () => () => {
      clearAnimationFrame();
      drainRef.current?.stop();
      if (resetTimerRef.current !== null) window.clearTimeout(resetTimerRef.current);
    },
    [clearAnimationFrame],
  );

  function handlePointerDown(event: PointerEvent<HTMLButtonElement>) {
    buttonProps.onPointerDown?.(event);
    if (event.defaultPrevented) return;
    if (event.button !== 0 || activePointerRef.current !== null) return;
    if (!begin("pointer")) return;
    activePointerRef.current = event.pointerId;
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  // Only the pointer that opened the hold can end it. A keyboard hold never
  // sets this ref, so a stray touch or pen cannot abort one that is still held.
  function handlePointerEnd(event: PointerEvent<HTMLButtonElement>) {
    if (activePointerRef.current !== event.pointerId) return;
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    activePointerRef.current = null;
    cancel();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    buttonProps.onKeyDown?.(event);
    if (event.defaultPrevented) return;
    if (event.repeat || (event.key !== " " && event.key !== "Enter")) return;
    event.preventDefault();
    // Remember which key opened the hold. Space and Enter both start one, and
    // releasing the other key must not cancel a hold it never started.
    if (begin("keyboard")) activeKeyRef.current = event.key;
  }

  function handleKeyUp(event: KeyboardEvent<HTMLButtonElement>) {
    buttonProps.onKeyUp?.(event);
    if (event.defaultPrevented) return;
    if (activeInputRef.current !== "keyboard" || event.key !== activeKeyRef.current) return;
    event.preventDefault();
    activeKeyRef.current = null;
    cancel();
  }

  return (
    <button
      {...buttonProps}
      type={buttonProps.type ?? "button"}
      className={cn(
        "relative isolate min-h-11 min-w-44 cursor-pointer touch-manipulation select-none overflow-hidden rounded-full border border-destructive/45 bg-destructive/10 px-5 text-sm font-semibold text-destructive outline-none active:scale-97 motion-safe:transition motion-safe:duration-150",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:cursor-not-allowed disabled:opacity-50 disabled:active:scale-100",
        className,
      )}
      data-status={status}
      disabled={disabled}
      onBlur={(event) => {
        buttonProps.onBlur?.(event);
        if (!event.defaultPrevented) cancel();
      }}
      onKeyDown={handleKeyDown}
      onKeyUp={handleKeyUp}
      onLostPointerCapture={(event) => {
        buttonProps.onLostPointerCapture?.(event);
        if (!event.defaultPrevented) handlePointerEnd(event);
      }}
      onPointerCancel={(event) => {
        buttonProps.onPointerCancel?.(event);
        if (!event.defaultPrevented) handlePointerEnd(event);
      }}
      onPointerDown={handlePointerDown}
      onPointerUp={(event) => {
        buttonProps.onPointerUp?.(event);
        if (!event.defaultPrevented) handlePointerEnd(event);
      }}
    >
      <span
        ref={fillRef}
        aria-hidden="true"
        // Never a Tailwind scale class here: it sets the CSS `scale` property, which
        // multiplies the transform painted each frame, so the fill would stay at zero.
        style={{ transform: "scaleX(0)" }}
        className="absolute inset-0 -z-10 origin-left bg-destructive/25"
      />
      <span className="flex items-center justify-center gap-2">
        {status === "confirmed" ? (
          confirmedContent ?? (
            <>
              <CheckGlyph />
              Confirmed
            </>
          )
        ) : (
          children
        )}
      </span>
    </button>
  );
}
